def minLargestGap(stations, k):
    n = len(stations)
    if n == 1:
        return 0
    gaps = [stations[i + 1] - stations[i] for i in range(n - 1)]

    def need(d):
        return sum((g - 1) // d for g in gaps)

    lo, hi = 1, max(gaps)
    while lo < hi:
        mid = (lo + hi) // 2
        if need(mid) <= k:
            hi = mid
        else:
            lo = mid + 1
    return lo
